from src.sandbox.environment import SandboxEnvironment; import tempfile, os; workspace = tempfile.mkdtemp(); print(f"Created workspace at: {workspace}"); sandbox = SandboxEnvironment(workspace); sandbox.create_container(); print("Initializing npm project..."); sandbox.execute_command("npm init -y"); print("Installing Express..."); sandbox.execute_command("npm install express"); server_code = """const express = require("express"); const app = express(); const port = 3005; app.get("/", (req, res) => { res.send("Hello World from sandbox container!"); }); app.listen(port, "0.0.0.0", () => { console.log(`Server running at http://localhost:${port}`); });"""; sandbox.write_file("server.js", server_code); print("Starting server..."); sandbox.execute_command("node server.js &"); print("Server should be running at http://localhost:3005")
